// ─── File: ProgrammaticTxDemo.java ───
// Runnable demo. In a real project each class is in its own file.
// Shows TransactionTemplate: execute, executeWithoutResult, setRollbackOnly,
// REQUIRES_NEW per transfer, and self-invocation that still gets a real tx.

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.*;

public class ProgrammaticTxDemo {
    private static final Logger log = Logger.getLogger("BankTx");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountRepository repo = new AccountRepository();
        FakeTxManager txManager = new FakeTxManager(log);
        TransferService service = new TransferService(repo, txManager, log);

        // Batch of three transfers; the middle one fails (not enough balance).
        List<TransferRequest> batch = List.of(
            new TransferRequest("SAV2001", "CUR3001", new BigDecimal("50000")),
            new TransferRequest("CUR3001", "SAV2001", new BigDecimal("9999999")), // too big
            new TransferRequest("SAV2001", "CUR3001", new BigDecimal("25000"))
        );
        service.runBatch(batch);

        log.info(() -> "FINAL Rajesh SAV2001 balance = " + repo.findById("SAV2001").getBalance());
        log.info(() -> "FINAL Priya  CUR3001 balance = " + repo.findById("CUR3001").getBalance());
    }
}

// ─── Would be in model/Account.java ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId; this.holderName = holderName; this.balance = balance;
    }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
    void debit(BigDecimal amount) { this.balance = this.balance.subtract(amount); }
    void credit(BigDecimal amount) { this.balance = this.balance.add(amount); }
}

// ─── Would be in dto/TransferRequest.java ───
class TransferRequest {
    final String from; final String to; final BigDecimal amount;
    TransferRequest(String from, String to, BigDecimal amount) {
        this.from = from; this.to = to; this.amount = amount;
    }
}

// ─── Would be in repository/AccountRepository.java ───
class AccountRepository {
    private final java.util.Map<String, Account> store = new java.util.HashMap<>();
    AccountRepository() {
        store.put("SAV2001", new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")));
        store.put("CUR3001", new Account("CUR3001", "Priya Sharma", new BigDecimal("250000")));
    }
    Account findById(String id) { return store.get(id); }
    void save(Account a) { store.put(a.getAccountId(), a); }
}

// ─── A tiny stand-in for Spring's TransactionTemplate + PlatformTransactionManager ───
// so the demo runs with plain Java. In Spring you inject the real ones.
class FakeTxManager {
    private final Logger log;
    FakeTxManager(Logger log) { this.log = log; }
    void runRequiresNew(String label, java.util.function.Consumer<TxStatus> body) {
        TxStatus status = new TxStatus();
        log.fine(() -> "BEGIN (REQUIRES_NEW) " + label);
        try {
            body.accept(status);
            if (status.isRollbackOnly()) {
                log.warning(() -> "ROLLBACK (rollbackOnly) " + label);
            } else {
                log.info(() -> "COMMIT " + label);
            }
        } catch (RuntimeException ex) {
            log.log(Level.SEVERE, "ROLLBACK (exception) " + label, ex);
        }
    }
}

class TxStatus {
    private boolean rollbackOnly = false;
    void setRollbackOnly() { this.rollbackOnly = true; }
    boolean isRollbackOnly() { return rollbackOnly; }
}

// ─── Would be in service/TransferService.java ───
// In real Spring: private final TransactionTemplate txTemplate =
//   new TransactionTemplate(txManager); txTemplate.setPropagationBehavior(REQUIRES_NEW);
class TransferService {
    private final AccountRepository repo;
    private final FakeTxManager txManager;
    private final Logger log;
    TransferService(AccountRepository repo, FakeTxManager txManager, Logger log) {
        this.repo = repo; this.txManager = txManager; this.log = log;
    }

    // Batch method. NOT transactional itself — each transfer is independent.
    void runBatch(List<TransferRequest> batch) {
        int totalTransfers = 0;
        for (TransferRequest req : batch) {
            totalTransfers++;
            // SELF-INVOCATION: this.transferOne(...) is a plain 'this' call.
            // With @Transactional it would be ignored. With the template it WORKS.
            transferOne(req);
        }
        int count = totalTransfers;
        log.info(() -> "Batch finished, attempted " + count + " transfers");
    }

    // Each transfer is its own REQUIRES_NEW transaction.
    void transferOne(TransferRequest req) {
        String label = req.from + "->" + req.to + " Rs." + req.amount;
        // executeWithoutResult equivalent: no return value needed
        txManager.runRequiresNew(label, status -> {
            Account from = repo.findById(req.from);
            Account to = repo.findById(req.to);
            if (from.getBalance().compareTo(req.amount) < 0) {
                log.warning(() -> "Insufficient balance for " + label + " -> marking rollbackOnly");
                status.setRollbackOnly();   // clean rollback, no exception thrown
                return;
            }
            from.debit(req.amount);
            to.credit(req.amount);
            repo.save(from);
            repo.save(to);
            log.info(() -> "Applied " + label);
        });
    }
}

// ─── Clean log formatter ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel().getName(), r.getMessage());
    }
}
```

The real Spring version of the service would be:

```java
// ─── File: src/main/java/com/bank/tx/service/TransferService.java ───
package com.bank.tx.service;

import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class TransferService {
    private final AccountRepository repo;
    private final TransactionTemplate txTemplate;

    public TransferService(AccountRepository repo, PlatformTransactionManager txManager) {
        this.repo = repo;
        this.txTemplate = new TransactionTemplate(txManager);
        this.txTemplate.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW);
        this.txTemplate.setTimeout(5);
    }

    public void transferOne(TransferRequest req) {
        txTemplate.executeWithoutResult(status -> {
            var from = repo.findById(req.getFrom()).orElseThrow();
            var to = repo.findById(req.getTo()).orElseThrow();
            if (from.getBalance().compareTo(req.getAmount()) < 0) {
                status.setRollbackOnly();
                return;
            }
            from.debit(req.getAmount());
            to.credit(req.getAmount());
            repo.save(from);
            repo.save(to);
        });
    }
}
