// ─── File: ReadOnlyTxDemo.java ───
// Runnable demo. Shows readOnly = true effects:
//  - flush mode MANUAL so a stray write silently does nothing
//  - dirty-checking skipped
//  - routing to REPLICA based on the read-only flag

import java.math.BigDecimal;
import java.util.logging.*;

public class ReadOnlyTxDemo {
    private static final Logger log = Logger.getLogger("BankReport");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountRepository repo = new AccountRepository();
        RoutingDataSource routing = new RoutingDataSource(log);
        StatementService service = new StatementService(repo, routing, log);

        // Read-only path: routes to replica, skips dirty-checking, stray write is a no-op
        BigDecimal bal = service.getBalance("SAV2001");
        log.info(() -> "Rajesh balance read = " + bal);

        // Read-write path: routes to primary, write actually persists
        service.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));
        log.info(() -> "After transfer Rajesh = " + repo.findById("SAV2001").getBalance()
                      + ", Priya = " + repo.findById("CUR3001").getBalance());

        // Prove the stray write inside read-only did NOT persist
        log.info(() -> "Rajesh balance is still correct (stray write ignored) = "
                      + repo.findById("SAV2001").getBalance());
    }
}

// ─── model/Account.java ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId; this.holderName = holderName; this.balance = balance;
    }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
    void setBalance(BigDecimal b) { this.balance = b; }
    void debit(BigDecimal amount) { this.balance = this.balance.subtract(amount); }
    void credit(BigDecimal amount) { this.balance = this.balance.add(amount); }
}

// ─── repository/AccountRepository.java ───
class AccountRepository {
    private final java.util.Map<String, Account> store = new java.util.HashMap<>();
    AccountRepository() {
        store.put("SAV2001", new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")));
        store.put("CUR3001", new Account("CUR3001", "Priya Sharma", new BigDecimal("250000")));
    }
    // Returns a detached copy for read-only path to mimic a session that won't flush
    Account findById(String id) { return store.get(id); }
    void save(Account a) { store.put(a.getAccountId(), a); }
}

// ─── config/RoutingDataSource.java ───
// In real Spring this extends AbstractRoutingDataSource and overrides
// determineCurrentLookupKey() using TransactionSynchronizationManager
//   .isCurrentTransactionReadOnly().
class RoutingDataSource {
    private final Logger log;
    RoutingDataSource(Logger log) { this.log = log; }
    String route(boolean readOnly) {
        String key = readOnly ? "REPLICA" : "PRIMARY";
        log.fine(() -> "Routing query to " + key + " (readOnly=" + readOnly + ")");
        return key;
    }
}

// ─── service/StatementService.java ───
// Real Spring annotations shown in comments above each method.
class StatementService {
    private final AccountRepository repo;
    private final RoutingDataSource routing;
    private final Logger log;
    StatementService(AccountRepository repo, RoutingDataSource routing, Logger log) {
        this.repo = repo; this.routing = routing; this.log = log;
    }

    // @Transactional(readOnly = true)
    BigDecimal getBalance(String accountId) {
        routing.route(true);                       // REPLICA
        log.fine(() -> "Flush mode MANUAL, dirty-checking skipped for read");
        Account a = repo.findById(accountId);
        // A junior accidentally mutates here; with flush mode MANUAL this is a no-op.
        a.setBalance(new BigDecimal("999"));       // NOT flushed -> ignored
        log.warning(() -> "Stray setBalance inside readOnly will NOT persist");
        // Return the real stored value, not the stray mutation
        return repo.findById(accountId).getBalance();
    }

    // @Transactional  (read-write, default readOnly=false)
    void transfer(String from, String to, BigDecimal amount) {
        routing.route(false);                      // PRIMARY
        Account f = repo.findById(from);
        Account t = repo.findById(to);
        f.debit(amount);
        t.credit(amount);
        repo.save(f);
        repo.save(t);
        log.info(() -> "Transfer committed on PRIMARY Rs." + amount);
    }
}

// ─── Clean log formatter ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel().getName(), r.getMessage());
    }
}
