// ─── File: TxEventDemo.java ───
// Runnable demo. Shows BEFORE_COMMIT, AFTER_COMMIT, AFTER_ROLLBACK phases
// and the default "drop if no transaction" behavior vs fallbackExecution=true.

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class TxEventDemo {
    private static final Logger log = Logger.getLogger("BankEvent");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountRepository repo = new AccountRepository();
        EventBus bus = new EventBus(log);
        bus.register(new AuditListener(log));     // BEFORE_COMMIT
        bus.register(new SmsListener(log));       // AFTER_COMMIT
        bus.register(new FailureListener(log));   // AFTER_ROLLBACK
        TransferService service = new TransferService(repo, bus, log);

        log.info(() -> "=== Successful transfer ===");
        service.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));

        log.info(() -> "=== Failing transfer (insufficient balance) ===");
        try {
            service.transfer("CUR3001", "SAV2001", new BigDecimal("9999999"));
        } catch (RuntimeException ex) {
            log.warning(() -> "Caller saw failure: " + ex.getMessage());
        }
    }
}

// ─── model/Account.java ───
class Account {
    private final String accountId; private final String holderName; private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId=id; holderName=name; balance=bal; }
    String getAccountId() { return accountId; }
    BigDecimal getBalance() { return balance; }
    void debit(BigDecimal a) { balance = balance.subtract(a); }
    void credit(BigDecimal a) { balance = balance.add(a); }
}

// ─── repository/AccountRepository.java ───
class AccountRepository {
    private final Map<String, Account> store = new HashMap<>();
    AccountRepository() {
        store.put("SAV2001", new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")));
        store.put("CUR3001", new Account("CUR3001", "Priya Sharma", new BigDecimal("250000")));
    }
    Account findById(String id) { return store.get(id); }
    void save(Account a) { store.put(a.getAccountId(), a); }
}

// ─── event/TransferCompletedEvent.java ───
class TransferCompletedEvent {
    final String from; final String to; final BigDecimal amount;
    TransferCompletedEvent(String from, String to, BigDecimal amount) {
        this.from=from; this.to=to; this.amount=amount;
    }
}

// ─── A tiny event bus that mimics Spring's transaction phases ───
enum Phase { BEFORE_COMMIT, AFTER_COMMIT, AFTER_ROLLBACK }
interface PhaseListener { Phase phase(); void handle(TransferCompletedEvent e); }

class EventBus {
    private final List<PhaseListener> listeners = new ArrayList<>();
    private final Logger log;
    EventBus(Logger log) { this.log = log; }
    void register(PhaseListener l) { listeners.add(l); }
    void fire(Phase phase, TransferCompletedEvent e) {
        for (PhaseListener l : listeners) {
            if (l.phase() == phase) l.handle(e);
        }
    }
}

// ─── service/TransferService.java ───
// Real Spring: @Transactional; publish with ApplicationEventPublisher.
class TransferService {
    private final AccountRepository repo; private final EventBus bus; private final Logger log;
    TransferService(AccountRepository repo, EventBus bus, Logger log) {
        this.repo=repo; this.bus=bus; this.log=log;
    }
    // @Transactional
    void transfer(String from, String to, BigDecimal amount) {
        TransferCompletedEvent event = new TransferCompletedEvent(from, to, amount);
        Account f = repo.findById(from);
        Account t = repo.findById(to);
        try {
            if (f.getBalance().compareTo(amount) < 0)
                throw new RuntimeException("Insufficient balance in " + from);
            f.debit(amount); t.credit(amount);
            repo.save(f); repo.save(t);
            // Spring: publishEvent here; listeners deferred to phases.
            bus.fire(Phase.BEFORE_COMMIT, event);  // still inside tx
            log.info(() -> "COMMIT transfer " + from + "->" + to + " Rs." + amount);
            bus.fire(Phase.AFTER_COMMIT, event);   // only after real commit
        } catch (RuntimeException ex) {
            log.severe(() -> "ROLLBACK transfer " + from + "->" + to);
            bus.fire(Phase.AFTER_ROLLBACK, event); // only on rollback
            throw ex;
        }
    }
}

// ─── listener/AuditListener.java — BEFORE_COMMIT ───
// Real Spring: @TransactionalEventListener(phase = BEFORE_COMMIT)
class AuditListener implements PhaseListener {
    private final Logger log; AuditListener(Logger log) { this.log = log; }
    public Phase phase() { return Phase.BEFORE_COMMIT; }
    public void handle(TransferCompletedEvent e) {
        // Participates in same tx: audit commits atomically with the transfer
        log.info(() -> "[BEFORE_COMMIT] audit row saved for " + e.from + "->" + e.to);
    }
}

// ─── listener/SmsListener.java — AFTER_COMMIT ───
// Real Spring: @TransactionalEventListener(phase = AFTER_COMMIT, fallbackExecution = true)
// combine with @Async so SMS does not block the request thread.
class SmsListener implements PhaseListener {
    private final Logger log; SmsListener(Logger log) { this.log = log; }
    public Phase phase() { return Phase.AFTER_COMMIT; }
    public void handle(TransferCompletedEvent e) {
        // Safe: data is durable, never a false confirmation
        log.info(() -> "[AFTER_COMMIT] SMS to " + e.from + ": transfer Rs." + e.amount + " successful");
    }
}

// ─── listener/FailureListener.java — AFTER_ROLLBACK ───
// Real Spring: @TransactionalEventListener(phase = AFTER_ROLLBACK)
class FailureListener implements PhaseListener {
    private final Logger log; FailureListener(Logger log) { this.log = log; }
    public Phase phase() { return Phase.AFTER_ROLLBACK; }
    public void handle(TransferCompletedEvent e) {
        log.severe(() -> "[AFTER_ROLLBACK] transfer reversed, notify ops for " + e.from);
    }
}

// ─── Clean log formatter ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel().getName(), r.getMessage());
    }
}
