        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Database db = new Database();
        PersistenceContext pc = new PersistenceContext(db, log);
        AccountRepository repo = new AccountRepository(db, pc, log);
        InterestService service = new InterestService(repo, pc, log);

        service.applyMonthlyInterest(new BigDecimal("0.01")); // 1% interest
