package com.bank.neft.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDateTime;

@Entity
@Table(name = "accounts")
public class Account {

    @Id
    @Column(name = "account_id")
    private String accountId;

    @Column(name = "holder_name", nullable = false)
    private String holderName;

    @Column(nullable = false)
    private BigDecimal balance;

    @Column(nullable = false)
    private String status;

    @Column(name = "updated_at")
    private LocalDateTime updatedAt;

    protected Account() {}

    public Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
        this.status = "ACTIVE";
        this.updatedAt = LocalDateTime.now();
    }

    public void debit(BigDecimal amount) {
        if (!"ACTIVE".equals(status)) throw new IllegalStateException("Account " + accountId + " is " + status);
        if (balance.compareTo(amount) < 0) throw new IllegalStateException("Insufficient balance: " + balance);
        balance = balance.subtract(amount);
        updatedAt = LocalDateTime.now();
    }

    public void credit(BigDecimal amount) {
        if (!"ACTIVE".equals(status)) throw new IllegalStateException("Account " + accountId + " is " + status);
        balance = balance.add(amount);
        updatedAt = LocalDateTime.now();
    }

    public String getAccountId() { return accountId; }
    public String getHolderName() { return holderName; }
    public BigDecimal getBalance() { return balance; }
    public String getStatus() { return status; }
}
