package com.bank.interest.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;

@Entity
@Table(name = "savings_accounts")
public class SavingsAccount {

    @Id
    @Column(name = "account_id")
    private String accountId;

    @Column(name = "holder_name", nullable = false)
    private String holderName;

    @Column(nullable = false)
    private BigDecimal balance;

    @Column(name = "interest_rate", nullable = false)
    private BigDecimal interestRate;

    @Column(name = "last_interest_date")
    private LocalDate lastInterestDate;

    @Column(nullable = false)
    private String status;

    protected SavingsAccount() {}

    public BigDecimal calculateMonthlyInterest() {
        // Monthly interest = balance × (annual rate / 12 / 100)
        return balance.multiply(interestRate)
            .divide(BigDecimal.valueOf(1200), 2, RoundingMode.HALF_UP);
    }

    public void creditInterest(BigDecimal interest) {
        if (!"ACTIVE".equals(status)) throw new IllegalStateException(accountId + " is " + status);
        this.balance = this.balance.add(interest);
        this.lastInterestDate = LocalDate.now();
    }

    public String getAccountId() { return accountId; }
    public String getHolderName() { return holderName; }
    public BigDecimal getBalance() { return balance; }
    public BigDecimal getInterestRate() { return interestRate; }
    public String getStatus() { return status; }
}
