// DECLARATIVE: @Transactional — single TX for ALL accounts
// PROBLEM: if account #49999 fails, ALL 50000 roll back!
package com.bank.interest.service;

import com.bank.interest.model.SavingsAccount;
import com.bank.interest.repository.SavingsAccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class DeclarativeInterestService {

    private final SavingsAccountRepository accountRepo;

    /**
     * DECLARATIVE: one big @Transactional for everything.
     * RISK: if ANY account fails → ALL work rolls back!
     * OK for small operations. BAD for batch processing 50,000 accounts.
     */
    @Transactional(rollbackFor = Exception.class, timeout = 60)
    public int calculateInterestDeclarative() {
        List<SavingsAccount> accounts = accountRepo.findByStatus("ACTIVE");
        log.info("[DECLARATIVE] Processing {} accounts in ONE transaction", accounts.size());

        int processed = 0;
        for (SavingsAccount account : accounts) {
            BigDecimal interest = account.calculateMonthlyInterest();
            account.creditInterest(interest);
            accountRepo.save(account);
            processed++;
            log.info("  {} → Rs.{} interest credited (balance: Rs.{})",
                account.getAccountId(), interest, account.getBalance());
        }

        // If exception here → ALL accounts roll back!
        log.info("[DECLARATIVE] Committed {} accounts in single TX", processed);
        return processed;
    }
}
