package com.bank.inquiry.service;

import com.bank.inquiry.dto.*;
import com.bank.inquiry.model.Account;
import com.bank.inquiry.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.List;

/**
 * CLASS-LEVEL @Transactional(readOnly = true):
 * - DEFAULT for ALL public methods = read-only
 * - Hibernate skips dirty checking (saves CPU)
 * - JDBC driver can route to READ REPLICA
 * - No accidental writes in query methods
 *
 * METHOD-LEVEL @Transactional (no readOnly) on write methods:
 * - OVERRIDES the class-level setting for THIS method only
 * - Enables dirty checking and writes
 */
@Service
@RequiredArgsConstructor
@Slf4j
@Transactional(readOnly = true)  // CLASS-LEVEL: all methods are read-only by default
public class AccountService {

    private final AccountRepository accountRepo;

    // ═══ READ METHODS: inherit class-level readOnly=true ═══
    // No @Transactional needed — class-level applies automatically
    // Hibernate: flush mode = MANUAL (no dirty checking — fast)
    // DataSource: can route to read replica

    public AccountSummary getAccount(String accountId) {
        log.info("[READ] getAccount {} — readOnly=true (class-level)", accountId);
        return accountRepo.findById(accountId)
            .map(AccountSummary::from)
            .orElseThrow(() -> new IllegalArgumentException("Not found: " + accountId));
    }

    public List<AccountSummary> getByType(String type) {
        log.info("[READ] getByType {} — readOnly=true (class-level)", type);
        return accountRepo.findByAccountType(type).stream()
            .map(AccountSummary::from).toList();
    }

    public List<AccountSummary> getHighBalance(BigDecimal minBalance) {
        log.info("[READ] getHighBalance > {} — readOnly=true (class-level)", minBalance);
        return accountRepo.findByBalanceGreaterThan(minBalance).stream()
            .map(AccountSummary::from).toList();
    }

    public long countActive() {
        log.info("[READ] countActive — readOnly=true (class-level)");
        return accountRepo.countByStatus("ACTIVE");
    }

    // ═══ WRITE METHODS: override class-level with writable TX ═══
    // Method-level @Transactional OVERRIDES class-level readOnly=true

    @Transactional  // OVERRIDES class-level readOnly=true → writable TX
    public AccountSummary deposit(DepositRequest request) {
        log.info("[WRITE] deposit {} Rs.{} — readOnly=false (method-level override)", 
            request.accountId(), request.amount());
        Account account = accountRepo.findById(request.accountId())
            .orElseThrow(() -> new IllegalArgumentException("Not found: " + request.accountId()));
        account.deposit(request.amount());
        accountRepo.save(account);
        return AccountSummary.from(account);
    }

    @Transactional(rollbackFor = Exception.class)  // writable + rollback on checked exceptions
    public AccountSummary withdraw(String accountId, BigDecimal amount) {
        log.info("[WRITE] withdraw {} Rs.{} — readOnly=false (method-level override)", accountId, amount);
        Account account = accountRepo.findById(accountId)
            .orElseThrow(() -> new IllegalArgumentException("Not found: " + accountId));
        account.withdraw(amount);
        accountRepo.save(account);
        return AccountSummary.from(account);
    }
}
