// REPEATABLE_READ: consistent snapshot — all reads see same data from TX start.
// NO non-repeatable reads. Safe for multi-query calculations.
package com.bank.valuation.service;

import com.bank.valuation.dto.PortfolioValuation;
import com.bank.valuation.model.*;
import com.bank.valuation.repository.*;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class RepeatableReadValuationService {

    private final AccountRepository accountRepo;
    private final HoldingRepository holdingRepo;

    /**
     * REPEATABLE_READ:
     * - First SELECT takes a SNAPSHOT. ALL subsequent reads in this TX see THAT snapshot.
     * - Even if another TX commits a deposit between our queries, we see the OLD data.
     * - CONSISTENT: balance and holdings are from the SAME point in time.
     * - COST: under heavy write contention, write-write conflicts cause serialization
     *   failures → app must RETRY.
     */
    @Transactional(isolation = Isolation.REPEATABLE_READ, readOnly = true)
    public PortfolioValuation calculateValuation(String accountId) {
        log.info("[REPEATABLE_READ] Reading balance (snapshot taken)...");
        Account account = accountRepo.findById(accountId)
            .orElseThrow(() -> new IllegalArgumentException("Not found: " + accountId));
        BigDecimal cashBalance = account.getBalance();

        // Another TX commits a deposit HERE — but WE still see the OLD balance.
        // REPEATABLE_READ snapshot is consistent. No non-repeatable read.

        log.info("[REPEATABLE_READ] Reading holdings (same snapshot — consistent)...");
        List<Holding> holdings = holdingRepo.findByAccountId(accountId);
        BigDecimal holdingsValue = holdings.stream()
            .map(Holding::getMarketValue)
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        return new PortfolioValuation(accountId, cashBalance, holdingsValue,
            cashBalance.add(holdingsValue), "REPEATABLE_READ",
            holdings.stream().map(h -> h.getSymbol() + "=" + h.getMarketValue()).toList());
    }
}
