// ─── File: .../service/EodReportService.java ───
// MVCC in action: this long-running read does NOT block concurrent writes.
// PostgreSQL keeps row versions — this TX reads a consistent SNAPSHOT.
package com.bank.reporting.service;

import com.bank.reporting.dto.EodReport;
import com.bank.reporting.repository.TransactionRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.time.LocalDate;

@Service
@RequiredArgsConstructor
@Slf4j
public class EodReportService {

    private final TransactionRepository txnRepo;

    /**
     * REPEATABLE_READ + readOnly:
     * - MVCC gives us a SNAPSHOT at the first SELECT.
     * - ALL subsequent reads see the SAME snapshot.
     * - Live transactions (deposits/withdrawals) continue UNBLOCKED.
     * - They create NEW row versions that we do NOT see (our snapshot is older).
     * - readOnly=true: Hibernate skips dirty checking (we are not writing).
     *
     * WITHOUT MVCC (pure locking):
     * - This query would LOCK all rows it reads for 30 seconds.
     * - All writes BLOCKED until report finishes. Unacceptable!
     *
     * VACUUM cost:
     * - Old row versions accumulate as "dead tuples."
     * - PostgreSQL AUTOVACUUM runs periodically to reclaim space.
     * - If autovacuum falls behind → table bloat → slower queries.
     * - Monitor: pg_stat_user_tables.n_dead_tup
     */
    @Transactional(isolation = Isolation.REPEATABLE_READ, readOnly = true, timeout = 120)
    public EodReport generateReport(LocalDate date) {
        log.info("[MVCC] Starting EOD report for {} — snapshot taken NOW", date);
        log.info("[MVCC] Live transactions continue unblocked (MVCC — readers don't block writers)");

        // Query 1: count — sees snapshot
        long totalTxns = txnRepo.countByTxnDate(date);

        // Simulate slow processing (30 seconds in real life)
        // During this time, new TXNs are being inserted — but we don't see them!
        log.info("[MVCC] Processing {} transactions (live writes continue in parallel)...", totalTxns);

        // Query 2: sum credits — SAME snapshot (consistent with Query 1)
        BigDecimal totalCredits = txnRepo.sumByDateAndType(date, "CREDIT");

        // Query 3: sum debits — SAME snapshot
        BigDecimal totalDebits = txnRepo.sumByDateAndType(date, "DEBIT");

        BigDecimal netFlow = totalCredits.subtract(totalDebits);

        log.info("[MVCC] Report complete: {} txns, credits={}, debits={}, net={}",
            totalTxns, totalCredits, totalDebits, netFlow);

        return new EodReport(date, totalTxns, totalCredits, totalDebits, netFlow,
            "MVCC snapshot — consistent read, zero write blocking");
    }
}
