// Concurrent writes: NOT blocked by the long-running report read (MVCC!)
package com.bank.reporting.service;

import com.bank.reporting.model.Transaction;
import com.bank.reporting.repository.TransactionRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.UUID;

@Service
@RequiredArgsConstructor
@Slf4j
public class LiveTransactionService {

    private final TransactionRepository txnRepo;

    /**
     * This write happens CONCURRENTLY with the EOD report read.
     * MVCC: this creates a NEW row version. The report's snapshot does NOT see it.
     * WITHOUT MVCC: this write would BLOCK waiting for the report's read lock.
     */
    @Transactional
    public String processDeposit(String accountId, BigDecimal amount) {
        String txnId = "TXN-" + UUID.randomUUID().toString().substring(0, 6).toUpperCase();
        Transaction txn = new Transaction(txnId, accountId, "CREDIT", amount, amount);
        txnRepo.save(txn);
        log.info("[LIVE] Deposit {} Rs.{} for {} — NOT visible to concurrent report snapshot",
            txnId, amount, accountId);
        return txnId;
    }
}
