// REQUIRED (default): joins existing TX or creates new
package com.bank.loan.service;

import com.bank.loan.dto.*;
import com.bank.loan.model.LoanAccount;
import com.bank.loan.repository.LoanAccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
@RequiredArgsConstructor
@Slf4j
public class DisbursementService {

    private final LoanAccountRepository accountRepo;
    private final AuditService auditService;         // REQUIRES_NEW — independent TX
    private final ComplianceService complianceService; // MANDATORY — must join this TX

    /**
     * REQUIRED (default): creates a NEW TX (none exists at controller level).
     *
     * Inside this method:
     * - complianceService.checkCompliance() runs in THIS TX (MANDATORY joins it)
     * - auditService.logDisbursement() runs in its OWN TX (REQUIRES_NEW — independent)
     */
    @Transactional(rollbackFor = Exception.class)
    public DisbursementResult disburse(DisbursementRequest request) {
        String borrowerId = request.borrowerAccountId();
        BigDecimal amount = request.amount();
        log.info("[DISBURSE-REQUIRED] Starting: Rs.{} to {}", amount, borrowerId);

        // Step 1: Compliance check (MANDATORY — joins this TX)
        boolean compliant = complianceService.checkCompliance(borrowerId, amount);
        if (!compliant) {
            // Audit the rejection (REQUIRES_NEW — commits even though we're about to return)
            auditService.logDisbursement(borrowerId, amount, "REJECTED", "Compliance check failed");
            return new DisbursementResult(borrowerId, amount, "REJECTED");
        }

        // Step 2: Debit loan pool
        LoanAccount pool = accountRepo.findById("POOL-001")
            .orElseThrow(() -> new IllegalStateException("Loan pool not found"));
        pool.debit(amount);
        accountRepo.save(pool);

        // Step 3: Credit borrower (may FAIL if account frozen → ROLLBACK debit)
        try {
            LoanAccount borrower = accountRepo.findById(borrowerId)
                .orElseThrow(() -> new IllegalArgumentException("Borrower not found: " + borrowerId));
            borrower.credit(amount);
            accountRepo.save(borrower);
        } catch (Exception e) {
            // Audit the failure BEFORE rollback (REQUIRES_NEW — commits independently!)
            auditService.logDisbursement(borrowerId, amount, "FAILED", e.getMessage());
            throw e;  // re-throw → proxy rolls back pool debit
        }

        // Step 4: Audit success (REQUIRES_NEW — commits independently)
        auditService.logDisbursement(borrowerId, amount, "SUCCESS", "Loan disbursed");

        log.info("[DISBURSE] Completed: Rs.{} to {}", amount, borrowerId);
        return new DisbursementResult(borrowerId, amount, "DISBURSED");
    }
}
