import java.math.BigDecimal;
import java.util.UUID;

@Service
@RequiredArgsConstructor
@Slf4j
public class PaymentService {

    private final PaymentRepository paymentRepo;
    private final AuditService auditService;  // REQUIRES_NEW — needs 2nd connection!

    /**
     * REQUIRED: gets connection #1 from pool.
     * Then calls auditService.logPayment() which needs connection #2.
     * Thread holds BOTH connections simultaneously!
     */
    @Transactional
    public String processPayment(String accountId, BigDecimal amount) {
        String paymentId = "PAY-" + UUID.randomUUID().toString().substring(0, 6).toUpperCase();
        String threadName = Thread.currentThread().getName();

        log.info("[PAYMENT] [{}] Processing {} — holding connection #1", threadName, paymentId);

        Payment payment = new Payment(paymentId, accountId, amount);
        payment.complete();
        paymentRepo.save(payment);

        // THIS CALL needs connection #2 (REQUIRES_NEW)
        // If pool is exhausted → waits → if ALL threads are in this state → DEADLOCK!
        auditService.logPayment(paymentId, "COMPLETED");

        log.info("[PAYMENT] [{}] Done {} — releasing connection #1", threadName, paymentId);
        return paymentId;
    }
}
