import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import javax.sql.DataSource;

@Component
@RequiredArgsConstructor
@Slf4j
@EnableScheduling
public class PoolMonitorConfig {

    private final DataSource dataSource;

    @Scheduled(fixedRate = 2000)
    public void logPoolStats() {
        if (dataSource instanceof HikariDataSource hikari) {
            HikariPoolMXBean pool = hikari.getHikariPoolMXBean();
            log.info("[POOL] active={}, idle={}, waiting={}, total={}",
                pool.getActiveConnections(),
                pool.getIdleConnections(),
                pool.getThreadsAwaitingConnection(),
                pool.getTotalConnections());

            // DEADLOCK SIGNAL: waiting > 0 AND active == maxPoolSize for sustained period
            if (pool.getThreadsAwaitingConnection() > 5) {
                log.warn("[POOL] HIGH CONTENTION: {} threads waiting for connections!",
                    pool.getThreadsAwaitingConnection());
            }
        }
    }
}
