package com.bank.bulk.service;

import com.bank.bulk.dto.TransferRequest;
import com.bank.bulk.model.Account;
import com.bank.bulk.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
@Slf4j
public class UnsafeTransferService {

    private final AccountRepository accountRepo;

    /**
     * UNSAFE: locks accounts in the ORDER passed by the caller.
     *
     * Thread-1: transfer(SAV2001 → CUR3001)
     *   → locks SAV2001 first, then CUR3001
     *
     * Thread-2: transfer(CUR3001 → SAV2001)
     *   → locks CUR3001 first, then SAV2001
     *
     * DEADLOCK:
     *   Thread-1 holds SAV2001, waits for CUR3001
     *   Thread-2 holds CUR3001, waits for SAV2001
     *   → circular wait → DB detects → kills one TX
     *   → PostgreSQL: "ERROR: deadlock detected"
     */
    @Transactional
    public String transferUnsafe(TransferRequest request) {
        String threadName = Thread.currentThread().getName();
        log.warn("[UNSAFE] [{}] Locking {} THEN {} (caller's order — deadlock risk!)",
            threadName, request.fromAccountId(), request.toAccountId());

        // Lock in caller's order — DANGEROUS!
        Account from = accountRepo.findByIdForUpdate(request.fromAccountId())
            .orElseThrow(() -> new IllegalArgumentException("Not found: " + request.fromAccountId()));

        // Thread may BLOCK here if another thread already locked this row
        Account to = accountRepo.findByIdForUpdate(request.toAccountId())
            .orElseThrow(() -> new IllegalArgumentException("Not found: " + request.toAccountId()));

        from.debit(request.amount());
        to.credit(request.amount());
        accountRepo.save(from);
        accountRepo.save(to);

        return "UNSAFE_COMPLETED";
    }
}
