     * SAFE: ALWAYS lock in ALPHABETICAL order by account ID.
     *
     * Thread-1: transfer(SAV2001 → CUR3001)
     *   → sorted: CUR3001 < SAV2001
     *   → locks CUR3001 first, then SAV2001
     *
     * Thread-2: transfer(CUR3001 → SAV2001)
     *   → sorted: CUR3001 < SAV2001
     *   → locks CUR3001 first, then SAV2001
     *
     * BOTH threads lock in SAME order → no cycle → NO DEADLOCK! ✅
     */
    @Transactional(rollbackFor = Exception.class, timeout = 10)
    public String transferSafe(TransferRequest request) {
        String threadName = Thread.currentThread().getName();

        // Sort by account ID → consistent lock order
        String firstId = request.fromAccountId().compareTo(request.toAccountId()) < 0
            ? request.fromAccountId() : request.toAccountId();
        String secondId = firstId.equals(request.fromAccountId())
            ? request.toAccountId() : request.fromAccountId();

        log.info("[SAFE] [{}] Locking {} THEN {} (alphabetical — no deadlock)",
            threadName, firstId, secondId);

        // Lock in consistent order
        Account first = accountRepo.findByIdForUpdate(firstId)
            .orElseThrow(() -> new IllegalArgumentException("Not found: " + firstId));
        Account second = accountRepo.findByIdForUpdate(secondId)
            .orElseThrow(() -> new IllegalArgumentException("Not found: " + secondId));

        // Determine which is from/to
        Account from = first.getAccountId().equals(request.fromAccountId()) ? first : second;
        Account to = first.getAccountId().equals(request.toAccountId()) ? first : second;

        from.debit(request.amount());
        to.credit(request.amount());
        accountRepo.save(from);
        accountRepo.save(to);

        log.info("[SAFE] [{}] Transfer complete: {} → {} Rs.{}",
            threadName, request.fromAccountId(), request.toAccountId(), request.amount());

        return "SAFE_COMPLETED";
    }
}
