package com.bank.crossborder.service;

import com.bank.crossborder.model.CrossBorderTransfer;
import com.bank.crossborder.repository.TransferRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.UUID;

@Service
@RequiredArgsConstructor
@Slf4j
public class GoodTransferService {

    private final TransferRepository transferRepo;
    private final OutboxEventWriter outboxWriter;

    /**
     * *** CORRECT: Short TX — DB only, no network call ***
     *
     * 1. Get connection from pool (~0ms)
     * 2. INSERT transfer (~5ms)
     * 3. INSERT outbox event (~5ms) ← in SAME TX as transfer
     * 4. COMMIT + release connection (~0ms)
     * Total: connection held 10ms (100% DB work, 0% network wait!)
     *
     * The partner bank call happens LATER via:
     * - Outbox relay → Kafka → Partner integration consumer → REST call
     * - NO DB connection held during the 3-second network call
     *
     * Max throughput with 20 connections and 10ms per TX:
     * 20 / 0.01 = 2000 transfers per second! (vs 7/s with pseudo-saga)
     */
    @Transactional
    public String transferGood(String fromAccount, String toIban, BigDecimal amount, String currency) {
        String id = "CBT-" + UUID.randomUUID().toString().substring(0, 6).toUpperCase();
        log.info("[GOOD] Short TX — DB only, no network call inside TX");

        CrossBorderTransfer transfer = new CrossBorderTransfer(id, fromAccount, toIban, amount, currency);
        transfer.markPending();  // status = PENDING_PARTNER (async completion)
        transferRepo.save(transfer);  // 5ms

        // Outbox event in SAME TX — guaranteed to commit together
        String payload = String.format(
            "{\"transferId\":\"%s\",\"toIban\":\"%s\",\"amount\":%s,\"currency\":\"%s\"}",
            id, toIban, amount, currency);
        outboxWriter.writeEvent(id, "CROSS_BORDER_INITIATED", payload);  // 5ms

        log.info("[GOOD] TX done in ~10ms. Partner call happens ASYNC via outbox relay.");
        return id;
        // Connection released after 10ms. Partner call = separate process, separate connection.
    }
}
