package com.bank.batch.service;

import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Slf4j
public class PaymentValidatorBad {

    /**
     * REQUIRED (default): joins the OUTER transaction.
     * When this throws → proxy calls setRollbackOnly() on the SHARED TX.
     * Even if the outer method catches the exception, the TX is POISONED.
     * Outer's commit → UnexpectedRollbackException!
     */
    @Transactional  // REQUIRED by default — shares outer TX
    public void validate(String accountId) {
        if ("INVALID".equals(accountId)) {
            log.error("[BAD VALIDATOR] Invalid account: {}", accountId);
            throw new RuntimeException("Invalid account: " + accountId);
            // Proxy catches this → marks shared TX as ROLLBACK-ONLY
            // The physical TX is now POISONED — cannot be committed anymore
        }
        log.info("[BAD VALIDATOR] Account {} is valid", accountId);
    }
}
