// GOOD: REQUIRES_NEW → separate TX → failure does NOT poison outer TX
package com.bank.batch.service;

import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

@Service
@Slf4j
public class PaymentValidatorGood {

    /**
     * REQUIRES_NEW: runs in its OWN physical transaction.
     * If this throws → only the INNER TX is marked rollback-only.
     * The OUTER TX is unaffected — can still commit valid payments.
     *
     * Alternative: don't use @Transactional on validator at all
     * (just a plain method that throws, caught by outer without TX involvement).
     */
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void validate(String accountId) {
        if ("INVALID".equals(accountId)) {
            log.error("[GOOD VALIDATOR] Invalid account: {} — only THIS TX rolls back", accountId);
            throw new RuntimeException("Invalid account: " + accountId);
            // Only this inner TX rolls back. Outer TX is SAFE.
        }
        log.info("[GOOD VALIDATOR] Account {} is valid", accountId);
    }
}
