package com.bank.imps.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "accounts")
public class Account {
    @Id @Column(name = "account_id") private String accountId;
    @Column(name = "holder_name") private String holderName;
    private String phone;
    private BigDecimal balance;
    private String status;

    protected Account() {}

    public void debit(BigDecimal amount) {
        if (balance.compareTo(amount) < 0) throw new IllegalStateException("Insufficient");
        balance = balance.subtract(amount);
    }

    public void credit(BigDecimal amount) {
        if (!"ACTIVE".equals(status)) throw new IllegalStateException(accountId + " is " + status);
        balance = balance.add(amount);
    }

    public String getAccountId() { return accountId; }
    public String getHolderName() { return holderName; }
    public String getPhone() { return phone; }
    public BigDecimal getBalance() { return balance; }
}
