package com.bank.imps.service;

import com.bank.imps.dto.ImpsRequest;
import com.bank.imps.model.Account;
import com.bank.imps.notification.SmsService;
import com.bank.imps.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
@Slf4j
public class BadImpsService {

    private final AccountRepository accountRepo;
    private final SmsService smsService;

    /**
     * BUG: SMS sent INSIDE the transaction.
     *
     * Scenario: transfer SAV2001 → FRZ9001 (frozen)
     * 1. debit SAV2001: balance 1,000,000 → 950,000
     * 2. SMS SENT: "Rs.50000 transferred successfully" ← ALREADY SENT!
     * 3. credit FRZ9001: THROWS (frozen) → TX ROLLBACK
     * 4. SAV2001 balance restored to 1,000,000 (rollback)
     *
     * RESULT: customer received SMS "transfer successful"
     *         but balance is UNCHANGED. Trust destroyed.
     *
     * @Transactional cannot undo the SMS — it is an EXTERNAL side effect.
     */
    @Transactional
    public String transferBad(ImpsRequest request) {
        Account from = accountRepo.findById(request.fromAccountId()).orElseThrow();
        Account to = accountRepo.findById(request.toAccountId()).orElseThrow();

        from.debit(request.amount());
        accountRepo.save(from);

        // *** BUG: SMS sent BEFORE credit attempt — cannot be undone on rollback! ***
        smsService.sendTransferConfirmation(from.getPhone(),
            request.fromAccountId(), request.toAccountId(), request.amount());

        to.credit(request.amount());  // THROWS for frozen account → ROLLBACK
        accountRepo.save(to);

        return "COMPLETED";
    }
}
