// CORRECT: fires ONLY after TX commits successfully
package com.bank.imps.event;

import com.bank.imps.notification.SmsService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.scheduling.annotation.Async;
import org.springframework.stereotype.Component;
import org.springframework.transaction.event.TransactionPhase;
import org.springframework.transaction.event.TransactionalEventListener;

@Component
@RequiredArgsConstructor
@Slf4j
public class TransferEventListener {

    private final SmsService smsService;

    /**
     * AFTER_COMMIT: fires ONLY after the DB transaction commits successfully.
     * If TX rolls back → this listener does NOT fire → no false SMS.
     *
     * Compare with plain @EventListener: fires IMMEDIATELY when event is published,
     * even if the TX rolls back later → would send false SMS!
     */
    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)
    @Async  // non-blocking — does not delay the response
    public void onTransferCompleted(TransferCompletedEvent event) {
        log.info("[AFTER_COMMIT] TX committed — safe to send SMS now");
        smsService.sendTransferConfirmation(event.senderPhone(),
            event.fromAccountId(), event.toAccountId(), event.amount());
    }

    /**
     * AFTER_ROLLBACK: fires ONLY after rollback — useful for alerting or cleanup.
     */
    @TransactionalEventListener(phase = TransactionPhase.AFTER_ROLLBACK)
    public void onTransferFailed(TransferCompletedEvent event) {
        log.warn("[AFTER_ROLLBACK] TX rolled back — NOT sending success SMS");
        // Could send a "transfer failed" SMS instead:
        // smsService.sendTransferFailed(event.senderPhone(), ...);
    }
}
