package com.bank.queue.repository;

import com.bank.queue.model.PendingPayment;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import java.util.List;
import java.util.Optional;

public interface PendingPaymentRepository extends JpaRepository<PendingPayment, String> {

    /**
     * SKIP LOCKED: pick next pending payment, SKIP rows locked by other transactions.
     * - FOR UPDATE: locks the selected row (prevents double-processing)
     * - SKIP LOCKED: if a row is already locked, skip it and try the next one
     * - LIMIT 1: pick only one at a time
     *
     * Multiple instances can call this concurrently — each gets a DIFFERENT row.
     * No deadlock. No waiting. No duplicate processing.
     */
    @Query(value = """
        SELECT * FROM pending_payments
        WHERE status = 'PENDING'
        ORDER BY created_at
        FOR UPDATE SKIP LOCKED
        LIMIT 1
        """, nativeQuery = true)
    Optional<PendingPayment> findNextPendingSkipLocked();

    // Batch version: pick up to N items
    @Query(value = """
        SELECT * FROM pending_payments
        WHERE status = 'PENDING'
        ORDER BY created_at
        FOR UPDATE SKIP LOCKED
        LIMIT :batchSize
        """, nativeQuery = true)
    List<PendingPayment> findNextBatchSkipLocked(int batchSize);
}
