// @Version + @Retryable: no locks, retry on conflict
package com.bank.queue.service;

import com.bank.queue.model.PendingPayment;
import com.bank.queue.repository.PendingPaymentRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.retry.annotation.Backoff;
import org.springframework.retry.annotation.Retryable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
@Slf4j
public class OptimisticRetryService {

    private final PendingPaymentRepository paymentRepo;

    /**
     * OPTIMISTIC LOCKING + RETRY:
     * - @Version on entity: Hibernate checks version on UPDATE
     * - If another TX updated the same row: ObjectOptimisticLockingFailureException
     * - @Retryable: auto-retry up to 3 times with exponential backoff
     *
     * Good for: low-contention scenarios (rare conflicts).
     * Bad for: high-contention hot rows (constant retries = wasted work).
     * For high contention: use pessimistic locking or SKIP LOCKED instead.
     */
    @Retryable(
        retryFor = ObjectOptimisticLockingFailureException.class,
        maxAttempts = 3,
        backoff = @Backoff(delay = 100, multiplier = 2))
    @Transactional
    public String processWithOptimisticRetry(String paymentId) {
        PendingPayment payment = paymentRepo.findById(paymentId)
            .orElseThrow(() -> new IllegalArgumentException("Not found: " + paymentId));

        log.info("[OPTIMISTIC] Processing {} (version={})", paymentId, payment.getVersion());

        payment.process(Thread.currentThread().getName());
        paymentRepo.save(payment);
        // If another TX committed a change to this row since we read it:
        // Hibernate: WHERE payment_id=? AND version=? → 0 rows updated → exception!
        // @Retryable catches it → re-reads → retries with new version

        return payment.getPaymentId();
    }
}
