@Entity
@Table(name = "investor_accounts")
public class InvestorAccount {
    @Id @Column(name = "account_id") private String accountId;
    @Column(name = "holder_name") private String holderName;
    private BigDecimal balance;
    @Column(name = "fund_units") private BigDecimal fundUnits;
