    protected InvestorAccount() {}

    public void deductSip(BigDecimal amount, BigDecimal nav) {
        if (balance.compareTo(amount) < 0) throw new IllegalStateException("Insufficient: " + balance);
        balance = balance.subtract(amount);
        BigDecimal newUnits = amount.divide(nav, 4, RoundingMode.HALF_UP);
        fundUnits = fundUnits.add(newUnits);
    }

    public String getAccountId() { return accountId; }
    public BigDecimal getBalance() { return balance; }
    public BigDecimal getFundUnits() { return fundUnits; }
    public Long getVersion() { return version; }
