package com.bank.sip.repository;

import com.bank.sip.model.InvestorAccount;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Query;
import jakarta.persistence.LockModeType;
import java.util.Optional;

public interface InvestorAccountRepository extends JpaRepository<InvestorAccount, String> {

    /**
     * @Lock(PESSIMISTIC_WRITE): SELECT ... FOR UPDATE
     * Locks THIS specific row. Other transactions WAIT until we commit.
     *
     * This is DIFFERENT from isolation level:
     * - Isolation (READ_COMMITTED): controls what ALL queries in the TX can SEE
     * - @Lock: controls which ROWS are exclusively HELD by this TX
     *
     * Used TOGETHER:
     * - READ_COMMITTED ensures we see only committed data (no dirty reads)
     * - PESSIMISTIC_WRITE ensures no other TX can modify this row until we commit
     */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("SELECT a FROM InvestorAccount a WHERE a.accountId = :id")
    Optional<InvestorAccount> findByIdForUpdate(String id);

    /**
     * @Lock(PESSIMISTIC_READ): SELECT ... FOR SHARE
     * Allows other readers but blocks writers.
     * Use when you need to ensure the value doesn't change but don't plan to write.
     */
    @Lock(LockModeType.PESSIMISTIC_READ)
    @Query("SELECT a FROM InvestorAccount a WHERE a.accountId = :id")
    Optional<InvestorAccount> findByIdForShare(String id);

    /**
     * @Lock(OPTIMISTIC): no DB lock — relies on @Version check at commit.
     * Same as no @Lock when entity has @Version.
     */
    @Lock(LockModeType.OPTIMISTIC)
    @Query("SELECT a FROM InvestorAccount a WHERE a.accountId = :id")
    Optional<InvestorAccount> findByIdOptimistic(String id);
}
