// NO @Lock: lost update — two threads read same balance, both deduct
package com.bank.sip.service;

import com.bank.sip.dto.SipDeductionRequest;
import com.bank.sip.model.InvestorAccount;
import com.bank.sip.repository.InvestorAccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
@Slf4j
public class UnsafeSipService {

    private final InvestorAccountRepository accountRepo;

    /**
     * UNSAFE: READ_COMMITTED isolation but NO @Lock.
     *
     * Thread-1: READ balance = 500000. Deduct 10000 → balance = 490000.
     * Thread-2: READ balance = 500000 (same! no lock). Deduct 10000 → balance = 490000.
     * Both COMMIT. Final balance = 490000. Should be 480000!
     *
     * LOST UPDATE: one deduction is lost because both read the same value.
     * Isolation level does NOT prevent this — isolation controls what you SEE,
     * not whether another TX can read the same row simultaneously.
     */
    @Transactional(isolation = Isolation.READ_COMMITTED)
    public String deductUnsafe(SipDeductionRequest request) {
        String thread = Thread.currentThread().getName();

        InvestorAccount account = accountRepo.findById(request.accountId())
            .orElseThrow();  // NO lock — another thread can read same row

        log.warn("[UNSAFE] [{}] Read balance={} (no lock — another thread may read same!)",
            thread, account.getBalance());

        account.deductSip(request.amount(), request.currentNav());
        accountRepo.save(account);

        log.warn("[UNSAFE] [{}] Saved balance={} (lost update possible!)",
            thread, account.getBalance());
        return "UNSAFE: " + account.getBalance().toString();
    }
}
