package com.bank.treasury.service;

import com.bank.treasury.model.TreasuryBond;
import com.bank.treasury.repository.TreasuryBondRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import java.time.LocalDate;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class TreasuryService {

    private final TreasuryBondRepository bondRepo;

    /**
     * This method demonstrates what happens INTERNALLY:
     * - Before this line executes, the proxy has ALREADY:
     *   1. Got a connection from HikariCP
     *   2. Set auto-commit=false
     *   3. Bound the connection to this thread
     * - TransactionSynchronizationManager.isActualTransactionActive() confirms TX is active
     * - All bondRepo calls use the SAME thread-bound connection
     */
    @Transactional(readOnly = true, timeout = 30)
    public List<TreasuryBond> findMaturingBonds(LocalDate beforeDate) {
        // Prove the TX is active and connection is bound
        boolean txActive = TransactionSynchronizationManager.isActualTransactionActive();
        boolean resourceBound = TransactionSynchronizationManager.hasResource(
            TransactionSynchronizationManager.getResourceMap().keySet().stream().findFirst().orElse(null));

        log.info("[INTERNALS] TX active: {}", txActive);
        log.info("[INTERNALS] Connection bound to thread: {}", !TransactionSynchronizationManager.getResourceMap().isEmpty());
        log.info("[INTERNALS] Current TX name: {}", TransactionSynchronizationManager.getCurrentTransactionName());
        log.info("[INTERNALS] TX read-only: {}", TransactionSynchronizationManager.isCurrentTransactionReadOnly());

        // This query uses the thread-bound connection (not a new one)
        List<TreasuryBond> bonds = bondRepo.findByMaturityDateBeforeAndStatus(beforeDate, "ACTIVE");

        log.info("[INTERNALS] Found {} maturing bonds. Connection will be released after proxy commits.", bonds.size());
        return bonds;
    }

    /**
     * For multiple DataSources:
     * @Transactional("secondaryTxManager") → selects specific manager
     *
     * Without the qualifier, Spring picks:
     * 1. The @Primary PlatformTransactionManager
     * 2. Or the sole candidate
     * 3. Or throws NoUniqueBeanDefinitionException if multiple without @Primary
     */
    @Transactional  // uses the default (auto-configured) JpaTransactionManager
    public void matureBond(String bondId) {
        TreasuryBond bond = bondRepo.findById(bondId).orElseThrow();
        bond.mature();
        bondRepo.save(bond);
        log.info("Bond {} matured", bondId);
    }
}
