package com.bank.margin.service;

import com.bank.margin.model.*;
import com.bank.margin.repository.*;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import java.math.BigDecimal;
import java.util.UUID;

@Service
@RequiredArgsConstructor
@Slf4j
public class MarginService {

    private final MarginAccountRepository accountRepo;
    private final MarginTradeRepository tradeRepo;

    /**
     * BOTH repository calls use the SAME connection because
     * TransactionSynchronizationManager binds the connection to THIS thread.
     *
     * Internal flow:
     * 1. Proxy: PlatformTransactionManager.getTransaction()
     *    → HikariCP.getConnection() → connection #7
     *    → TransactionSynchronizationManager.bindResource(dataSource, conn#7)
     *
     * 2. accountRepo.findById() → DataSourceUtils.getConnection(dataSource)
     *    → TransactionSynchronizationManager.getResource(dataSource) → conn#7 (ThreadLocal!)
     *
     * 3. tradeRepo.save() → DataSourceUtils.getConnection(dataSource)
     *    → same conn#7 (SAME thread, SAME ThreadLocal entry)
     *
     * 4. Proxy: commit → conn#7.commit()
     *    → TransactionSynchronizationManager.unbindResource(dataSource)
     *    → conn#7 returned to HikariCP
     */
    @Transactional
    public String openMarginTrade(String accountId, String symbol, BigDecimal amount) {
        // Log thread-local binding proof
        log.info("[TX-INTERNALS] Thread: {}", Thread.currentThread().getName());
        log.info("[TX-INTERNALS] TX active: {}",
            TransactionSynchronizationManager.isActualTransactionActive());
        log.info("[TX-INTERNALS] Resources bound: {}",
            TransactionSynchronizationManager.getResourceMap().size());

        // Call 1: uses connection from ThreadLocal
        MarginAccount account = accountRepo.findById(accountId).orElseThrow();

        // Call 2: uses SAME connection from ThreadLocal (not a new one!)
        String tradeId = "MGT-" + UUID.randomUUID().toString().substring(0, 6).toUpperCase();
        MarginTrade trade = new MarginTrade(tradeId, accountId, symbol, amount);
        tradeRepo.save(trade);

        log.info("Margin trade {} opened. Both repo calls used same connection (thread-local).", tradeId);
        return tradeId;
    }
}
