import java.util.*;
import java.util.logging.*;

public class ReadOnlyWriteTrapDemo {
    private static final Logger log = Logger.getLogger("BankReadOnly");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountRepository repo = new AccountRepository(log);

        log.info(() -> "=== BROKEN: transfer under @Transactional(readOnly=true) ===");
        BrokenAccountService broken = new BrokenAccountService(repo, log);
        broken.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));
        log.info(() -> "After broken transfer -> Rajesh = " + repo.readFromStore("SAV2001")
                      + ", Priya = " + repo.readFromStore("CUR3001") + " (UNCHANGED, write dropped!)");

        log.info(() -> "=== FIXED: transfer under writable @Transactional ===");
        FixedAccountService fixed = new FixedAccountService(repo, log);
        fixed.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));
        log.info(() -> "After fixed transfer -> Rajesh = " + repo.readFromStore("SAV2001")
                      + ", Priya = " + repo.readFromStore("CUR3001") + " (money truly moved)");
    }
}

// ─── model/Account.java ───
class Account {
    private final String accountId; private String holderName; private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId=id; holderName=name; balance=bal; }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    void setHolderName(String n) { this.holderName = n; }
    BigDecimal getBalance() { return balance; }
    void debit(BigDecimal a) { balance = balance.subtract(a); }
    void credit(BigDecimal a) { balance = balance.add(a); }
    Account copy() { return new Account(accountId, holderName, balance); }
}

// ─── repository/AccountRepository.java ───
// Simulates a Hibernate persistence context. Managed entities live in
// 'managed'. The durable database is 'store'. flush() copies managed state
// into store ONLY when flush mode is AUTO. MANUAL means nothing is written.
class AccountRepository {
    enum FlushMode { AUTO, MANUAL }
    private final Map<String, Account> store = new HashMap<>();
    private final Map<String, Account> managed = new HashMap<>();
    private FlushMode flushMode = FlushMode.AUTO;
    private final Logger log;

    AccountRepository(Logger log) {
        this.log = log;
        store.put("SAV2001", new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")));
        store.put("CUR3001", new Account("CUR3001", "Priya Sharma", new BigDecimal("250000")));
    }

    void setFlushMode(FlushMode m) { this.flushMode = m; log.fine(() -> "FlushMode = " + m); }

    // Loads a managed copy the caller can mutate (like a managed JPA entity).
    Account findManaged(String id) {
        Account m = managed.get(id);
        if (m == null) { m = store.get(id).copy(); managed.put(id, m); }
        return m;
    }

    BigDecimal readFromStore(String id) { return store.get(id).getBalance(); }

    // Spring calls this at commit. With MANUAL, pending changes are discarded.
    void commit() {
        if (flushMode == FlushMode.AUTO) {
            managed.forEach((id, a) -> store.put(id, a.copy()));
            log.fine(() -> "COMMIT: AUTO flush -> " + managed.size() + " change(s) written to DB");
        } else {
            log.severe(() -> "COMMIT: MANUAL flush -> " + managed.size()
                            + " pending change(s) SILENTLY DISCARDED (no error)");
        }
        managed.clear();
    }
}

// ─── service/BrokenAccountService.java — class-level readOnly poisons the write ───
// @Transactional(readOnly = true)   <-- imagine this on the CLASS
class BrokenAccountService {
    private final AccountRepository repo; private final Logger log;
    BrokenAccountService(AccountRepository repo, Logger log) { this.repo=repo; this.log=log; }

    // Inherits class-level readOnly -> FlushMode.MANUAL -> writes dropped.
    void transfer(String from, String to, BigDecimal amount) {
        repo.setFlushMode(AccountRepository.FlushMode.MANUAL); // what readOnly=true does
        Account f = repo.findManaged(from);
        Account t = repo.findManaged(to);
        f.debit(amount);
        t.credit(amount);
        log.info(() -> "BROKEN transfer applied in memory " + from + "->" + to + " Rs." + amount);
        repo.commit(); // discards the changes silently
    }
}

// ─── service/FixedAccountService.java — query methods readOnly, writes writable ───
class FixedAccountService {
    private final AccountRepository repo; private final Logger log;
    FixedAccountService(AccountRepository repo, Logger log) { this.repo=repo; this.log=log; }

    // @Transactional(readOnly = true) — correct, this method only reads
    BigDecimal getBalance(String id) {
        repo.setFlushMode(AccountRepository.FlushMode.MANUAL);
        return repo.readFromStore(id);
    }

    // @Transactional  (writable) — method-level setting OVERRIDES any class default
    void transfer(String from, String to, BigDecimal amount) {
        repo.setFlushMode(AccountRepository.FlushMode.AUTO); // writable: AUTO flush
        Account f = repo.findManaged(from);
        Account t = repo.findManaged(to);
        if (f.getBalance().compareTo(amount) < 0)
            throw new IllegalStateException("Insufficient balance in " + from);
        f.debit(amount);
        t.credit(amount);
        log.info(() -> "FIXED transfer applied " + from + "->" + to + " Rs." + amount);
        repo.commit(); // AUTO flush writes to DB
    }
}

// ─── Clean log formatter ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel().getName(), r.getMessage());
    }
}
