The real Spring structure, with a central handler and a committed state machine:

```java
// ─── File: src/main/java/com/bank/truth/controller/SafeTransferController.java ───
package com.bank.truth.controller;

import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;

@RestController
@RequestMapping("/api/v1/transfers")
public class SafeTransferController {
    private final TransferService service;
    public SafeTransferController(TransferService service) { this.service = service; }

    @PostMapping
    public ResponseEntity<TransferResponse> transfer(@RequestBody TransferRequest req) {
        // NO try-catch that hides failure. Exceptions flow to GlobalExceptionHandler.
        Transfer t = service.transfer(req.from(), req.to(), req.amount());
        // 200 ONLY when the committed status is COMPLETED.
        HttpStatus code = t.getStatus() == TransferStatus.COMPLETED
            ? HttpStatus.OK : HttpStatus.UNPROCESSABLE_ENTITY;
        return ResponseEntity.status(code)
            .body(new TransferResponse(t.getTransferId(), t.getStatus()));
    }
}
